insert into data_layer_runs (layer_id, source, source_url, license, record_count, notes) values ($q$restricoes_rmsp$q$, $q$guaruja$q$, $q$https://www.guaruja.sp.gov.br/guaruja-instala-nova-sinalizacao-para-caminhoes-na-rua-valdomiro-macario (15/04/2025) ; https://www.guaruja.sp.gov.br/prefeitura-autoriza-obras-para-limitar-o-transito-de-caminhoes-na-rua-valdomiro-macario (30/04/2025)$q$, $q$Notícias da Prefeitura de Guarujá: só os fatos, com link (não há ato publicado). Geometria: OpenStreetMap (ODbL 1.0, © colaboradores do OpenStreetMap).$q$, 2, $q$Regra pela sinalização regulamentadora (placa instalada pela Ecovias a pedido da Secretaria de Mobilidade) e por barreira física de esferas de concreto a partir do segundo trecho, desde 30/04/2025. No OSM a rua se chama 'Rua Waldomiro Macário' (com W), inclusive as alças da Rod. Cônego Domênico Rangoni que entram nela (fora da regra). O começo da rua, entre a rodovia e o acesso ao Assaí, é livre: a proibição vale do acesso ao Assaí para oeste.$q$);
